let production = data.series[0].fields[0].values;
let intensity = data.series[0].fields[1].values;
let country = data.series[0].fields[2].values;
let region = data.series[0].fields[3].values;
// let regionSet = new Map(Array.from(new Set(region)).map((v, i) => [v, i]));

let multiRegion = (new Set(region)).size > 1;

let regionSet = new Map([
  ["Africa", 0],
  ["Asia", 1],
  ["Latin America and Caribbean", 2],
  ["Europe", 3],
  ["North America", 4],
  ["Oceania", 5],
  ["Middle East", 6]
]);

let colors = [];
if (multiRegion) {
  colors = region.map(r => regionSet.get(r));
} else {
  colors = [...country].map((c, globalIdx) => [c,globalIdx])
  colors.sort(([c1], [c2]) => c1.localeCompare(c2));
  colors = colors.map(([c, globalIdx], sortedIdx) => [globalIdx, sortedIdx]);
  colors.sort(([globalIdx1],[globalIdx2]) => globalIdx1-globalIdx2);
  colors = colors.map(([globalIdx,sortedIdx]) => sortedIdx);
}

let cmax = multiRegion ? regionSet.size : colors.length;

let sliderState = 0;
let minMaxState = 'top';

const co2Sorted = production
  .map((p,i) => [p*intensity[i], i]);
co2Sorted.sort(([a],[b]) => a-b);
const co2Index = co2Sorted.map(([c,i]) => i);

const getTrace = (skipCount = sliderState, minMax = minMaxState) => {
  const keeptIdx = new Set(minMax === 'top'
    ? co2Index.slice(skipCount)
    : co2Index.slice(0,  co2Index.length-skipCount)
  );
    // production
    // .map((p, i) => [p,i])
    // .filter(([p,i]) => minMax === 'top' ? p*intensity[i] >= skipCount : p*intensity[i] <= skipCount)
    // .map(([p,i]) => i));
  let res = {
    x: production
      .filter((p,i) => keeptIdx.has(i))
      .reduce(([sum, arr], p) => [sum+p, [...arr, sum+p/2]], [0, []])[1],
    y: intensity.filter((p,i) => keeptIdx.has(i)),
    customdata: production.map((p,i) => [p, p*intensity[i]/1000]).filter((p,i) => keeptIdx.has(i)),
    width: production.filter((p,i) => keeptIdx.has(i)),
    text: country.filter((p,i) => keeptIdx.has(i)),
    hovertemplate: '%{text}<br>Production: %{customdata[0]:.0f} TWh<br>Intensity: %{y}<br>Emission: %{customdata[1]:.1f} MT<extra></extra>',
    marker: {
      color: colors.filter((p,i) => keeptIdx.has(i)),
      cmin: 0,
      cmax: cmax-1,
      colorscale: 'Portland',
    }
  };
  return res
}

const forUpdate = (obj) => Object.fromEntries(
  Object.entries(obj)
    .filter(([k,v]) => typeof k === "string")
    .map(([k,v]) => [k, [v]])
  );

let trace = getTrace();

var sliderSteps = production
.map((p, i) => ({
  method: 'skip',
  value: i,
  data: i,
  label: i
}));

let layout = {
  updatemenus: [{
    buttons: [
      { 
        label: 'Top',
        method: 'skip',
        name: 'top',
      },
      { 
        label: 'Bottom',
        method: 'skip',
        name: 'bottom',
      }],
      x: 0,
      y: 0,
      yanchor: 'top',
      xanchor: 'left',
      pad: {t: 50, l: 00},
  }],
  sliders: [{
    pad: {t: 70, l:100},
    currentvalue: {
      xanchor: 'right',
      prefix: 'skip bottom emitters: ',
      font: {
        color: '#888',
        size: 20
      }
    },
    steps: sliderSteps
  }],
  //  xaxis: {
  //     rangeslider: {}
  // }
}



const debouncedUpdate = _.debounce((event, sliderValue, minMax) => {
    sliderState = sliderValue;
    minMaxState = minMax;
    const up = forUpdate(getTrace(sliderState, minMax));
    Plotly.update(event.currentTarget, up, 
      {"sliders[0].currentvalue.prefix": `skip ${minMaxState === 'top' ? 'bottom':'top'} emitters: `});
  }, 10);

$(".js-plotly-plot").off("plotly_sliderchange")

$(".js-plotly-plot").on("plotly_sliderchange", (event, data) => {
  debouncedUpdate(event, Number.parseFloat(data.step.value), minMaxState)
});

$(".js-plotly-plot").off("plotly_buttonclicked")
$(".js-plotly-plot").on("plotly_buttonclicked", (event, data) => {
  debouncedUpdate(event, sliderState, data.button.name)
});

return { data: [trace], layout };

